original_name,
content_type,
size,
is_private,
biz_type,
biz_id,
created_at,
updated_at,
created_by,
updated_by
FROM
file_record


        is_deleted = #{isDeleted}


        AND is_private = #{query.isPrivate}


        AND delete_source IN

            #{source}



        AND delete_source = #{query.deleteSource}


        AND created_by = #{query.ownerUserId}


        AND biz_type = #{query.bizType}


        AND biz_id = #{query.bizId}


        AND content_type LIKE CONCAT(#{query.contentType}, '%')


        AND original_name LIKE CONCAT('%', #{query.originalName}, '%')


        AND created_at  >=  #{query.startTime}
        AND created_at  <=  #{query.endTime}


ORDER BY
created_at DESC

